# Geometry is read at the original point computation time, never treated as fresh now.
function Read-NativeCallerDatePacket($Raw){
 $hasError=@($Raw.PSObject.Properties.Name)-ccontains'isError';$fields=if($hasError){@('content','isError')}else{@('content')};Assert-NativeSeedFields $Raw $fields
 Need ((!$hasError-or($Raw.isError-is[bool]-and!$Raw.isError))-and$Raw.content-is[array]-and$Raw.content.Count-eq1)
 $text=$Raw.content[0];Assert-NativeSeedFields $text @('type','text');Need ($text.type-is[string]-and$text.type-ceq'text'-and$text.text-is[string]-and[Text.Encoding]::UTF8.GetByteCount($text.text)-le65536)
 return ConvertFrom-ZeroProviderObject $text.text
}
